<template><section class="filters page-card"><BaseSelect label="Panel" :model-value="selectedPanelId" @update:model-value="$emit('update:selectedPanelId',$event)"><option value="all" :disabled="!canComparePanels">{{ canComparePanels ? 'Comparar todos los paneles' : 'No hay suficientes paneles para comparar' }}</option><option v-for="panel in panels" :key="panel.id" :value="panel.id">{{ panelLabel(panel) }}</option></BaseSelect><BaseSelect label="Circuito" :model-value="selectedCircuitId" :disabled="selectedPanelId === 'all' || !circuitOptions.length" @update:model-value="$emit('update:selectedCircuitId',$event)"><option value="all">{{ selectedPanelId === 'all' ? 'Selecciona un panel' : 'Comparar circuitos del panel' }}</option><option v-for="circuit in circuitOptions" :key="circuit.id" :value="circuit.id">{{ circuit.nombre }}</option></BaseSelect><BaseSelect label="Mostrar últimos" :model-value="rangeMinutes" @update:model-value="$emit('update:rangeMinutes',Number($event))"><option v-for="range in timeRanges" :key="range.value" :value="range.value">{{ range.label }}</option></BaseSelect><div class="scope-note"><span>Contexto activo</span><strong>{{ visibleCount }} {{ visibleCount === 1 ? 'circuito' : 'circuitos' }}</strong></div></section></template>
<script setup>import BaseSelect from '../common/BaseSelect.vue';import { panelLabel } from '../../composables/useRealtimeData';defineProps({panels:Array,canComparePanels:Boolean,selectedPanelId:[String,Number],selectedCircuitId:[String,Number],rangeMinutes:Number,circuitOptions:Array,visibleCount:Number});defineEmits(['update:selectedPanelId','update:selectedCircuitId','update:rangeMinutes']);const timeRanges=[{value:1,label:'1 minuto'},{value:2,label:'2 minutos'},{value:5,label:'5 minutos'}];</script>
<style scoped>.filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding:18px}.filters :deep(.field){gap:7px}.scope-note{display:grid;align-content:center;gap:6px;padding:0 14px;border-left:1px solid rgba(100,133,171,.2)}.scope-note span{color:#d6e2f0;font-size:13px}.scope-note strong{color:#fff;font-size:15px}@media(max-width:1050px){.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.scope-note{border-left:0;padding:9px 0;border-top:1px solid rgba(100,133,171,.2)}}@media(max-width:560px){.filters{grid-template-columns:1fr;padding:14px}.scope-note{grid-column:auto}}</style>
